// var: variable global
var variable_var = "Soy var";
// let: variable local
let variable_let = "Soy let";
// const: constante 
const variable_const = "Soy const";

// TIPOS DE DATOS
// Número
let numero = 10;
let decimal = 3.14;
// String
let texto = "Hola mundo";
// Boolean
let activo = true;
// Null
let vacio = null;
// Undefined
let indefinido;
// Array
const numeros = [1, 2, 3, 4, 5];
// Matriz
const matriz = [
  [1, 2],
  [3, 4]
];
// Objeto
const persona = {
  nombre: "Ana",
  edad: 25
};
// Operaciones +,-,*,/ y las de Math
let suma = numero + (decimal*Math.PI);

// ESTRUCTURAS DE CONTROL DE FLUJO
// For
let suma_lista = 0;
for (let i = 0; i < numeros.length; i++) {
  suma_lista = suma_lista + numeros[i];
}
// Condicional
let resultado = "";
if (numero > 5) {
  resultado = "Mayor a 5";
} else {
  resultado = "Menor o igual a 5";
}

// var vs let

var ejemplo_var = "global";
if (true) {
  // cambia la variable definida antes de if
  var ejemplo_var = "cambio con var"; 
}

let ejemplo_let = "global";

if (true) {
  //parecen variables independientes y no cambia la de afuera
  let ejemplo_let = "solo dentro del bloque"; 
}

return [
  {
    json: {
      var: variable_var,
      let: variable_let,
      const: variable_const,
      numero: numero,
      decimal: decimal,
      texto: texto,
      booleano: activo,
      null: vacio,
      undefined: indefinido,
      array: numeros,
      matriz: matriz,
      objeto: persona,
      suma: suma,
      suma_lista: suma_lista,
      resultado: resultado,
      ejemplo_var: ejemplo_var,
      ejemplo_let: ejemplo_let
    }
  }
];
